CREATE TEMP TABLE supervisor_preservation_check(tabela text PRIMARY KEY,digest text) ON COMMIT DROP;
INSERT INTO supervisor_preservation_check SELECT 'diaristas',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.diaristas t;
INSERT INTO supervisor_preservation_check SELECT 'pedidos',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.pedidos t;
INSERT INTO supervisor_preservation_check SELECT 'lojas',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.lojas t;
INSERT INTO supervisor_preservation_check SELECT 'diarias',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.diarias t;
INSERT INTO supervisor_preservation_check SELECT 'pedido_escalas',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.pedido_escalas t;
INSERT INTO supervisor_preservation_check SELECT 'financeiro_lancamentos',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.financeiro_lancamentos t;
INSERT INTO supervisor_preservation_check SELECT 'cobrancas',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.cobrancas t;
INSERT INTO supervisor_preservation_check SELECT 'cobranca_itens',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.cobranca_itens t;
INSERT INTO supervisor_preservation_check SELECT 'cobranca_recebimentos',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.cobranca_recebimentos t;
INSERT INTO supervisor_preservation_check SELECT 'pagamento_lotes',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]')::text) FROM public.pagamento_lotes t;
-- Additive ledger. No UPDATE/DELETE/seed of existing business records.
create table public.supervisor_registros(
 id bigint generated by default as identity primary key,
 tipo text not null check(tipo in ('adiantamento','passagem','acerto','fechamento','estorno')),
 pedido_id bigint references public.pedidos(id),diarista_id bigint references public.diaristas(id),
 dados jsonb not null,chave text not null unique,autor text not null,criado_em timestamptz not null default now()
);
create index supervisor_worker_order on public.supervisor_registros(diarista_id,pedido_id,id);
alter table public.supervisor_registros enable row level security;
revoke all on public.supervisor_registros from public,anon,authenticated;
grant select on public.supervisor_registros to authenticated;
create policy supervisor_finance_read on public.supervisor_registros for select to authenticated using((select direct_private.member_role()) in ('admin','financeiro'));
create trigger audit_supervisor after insert or update or delete on public.supervisor_registros for each row execute function direct_private.log_change();
create trigger supervisor_revision after insert or update or delete on public.supervisor_registros for each statement execute function direct_private.bump_revision();

create function public.direct_supervisor_registros(p jsonb default '{}') returns jsonb language sql stable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(r) order by id),'[]') from public.supervisor_registros r;
$$;
revoke all on function public.direct_supervisor_registros(jsonb) from public,anon;grant execute on function public.direct_supervisor_registros(jsonb) to authenticated;

-- Private helpers own the transaction because payment batches are not writable through the Data API.
create function direct_private.supervisor_plan(worker bigint,ord bigint) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r record;x jsonb;gross bigint:=0;travel bigint:=0;remaining bigint;credit bigint:=0;discount bigint;take bigint;ids jsonb:='[]';pids jsonb:='[]';deductions jsonb:='[]';cash jsonb:='{}';pcash jsonb:='{}';
begin
 if auth.uid() is null or coalesce(direct_private.member_role(),'') not in ('admin','financeiro') then raise exception 'Somente administrador ou Financeiro.' using errcode='42501';end if;
 for r in select d.* from public.diarias d join public.pedido_escalas s on s.id=d.pedido_escala_id where d.diarista_id=worker and s.pedido_id=ord and d.data_pagamento is null order by d.data,d.id loop
 if r.valor_centavos is null then raise exception 'Complete os valores das diárias antes de conferir o acerto.';end if;gross:=gross+r.valor_centavos;ids:=ids||to_jsonb(r.id);end loop;
 for r in select * from public.supervisor_registros a where a.tipo='passagem' and a.diarista_id=worker and a.pedido_id=ord and not exists(select 1 from public.supervisor_registros v where v.tipo='estorno' and (v.dados->>'registro_id')::bigint=a.id) and not exists(select 1 from public.supervisor_registros v where v.tipo='acerto' and v.dados->'passagem_ids' @> jsonb_build_array(a.id)) order by a.id loop travel:=travel+(r.dados->>'valor_centavos')::bigint;pids:=pids||to_jsonb(r.id);end loop;
 remaining:=gross+travel;
 for r in select a.id,(a.dados->>'valor_centavos')::bigint-coalesce((select sum((v->>'valor_centavos')::bigint) from public.supervisor_registros c cross join lateral jsonb_array_elements(c.dados->'abatimentos') v where c.tipo='acerto' and (v->>'id')::bigint=a.id),0) available from public.supervisor_registros a where a.tipo='adiantamento' and a.diarista_id=worker and a.pedido_id=ord and not exists(select 1 from public.supervisor_registros v where v.tipo='estorno' and (v.dados->>'registro_id')::bigint=a.id) order by a.id loop
 credit:=credit+r.available;take:=least(remaining,r.available);if take>0 then deductions:=deductions||jsonb_build_object('id',r.id,'valor_centavos',take);remaining:=remaining-take;end if;end loop;
 discount:=gross+travel-remaining;
 for r in select d.* from public.diarias d join public.pedido_escalas s on s.id=d.pedido_escala_id where d.diarista_id=worker and s.pedido_id=ord and d.data_pagamento is null order by d.data,d.id loop take:=least(discount,r.valor_centavos);cash:=cash||jsonb_build_object(r.id::text,r.valor_centavos-take);discount:=discount-take;end loop;
 for x in select value from jsonb_array_elements(pids) loop select (dados->>'valor_centavos')::bigint into take from public.supervisor_registros where id=(x#>>'{}')::bigint;pcash:=pcash||jsonb_build_object(x#>>'{}',take-least(discount,take));discount:=greatest(0,discount-take);end loop;
 return jsonb_build_object('diarista_id',worker,'pedido_id',ord,'diaria_ids',ids,'passagem_ids',pids,'diarias_centavos',gross,'passagens_centavos',travel,'abatimentos',deductions,'adiantamentos_centavos',gross+travel-remaining,'saldo_centavos',remaining,'credito_remanescente_centavos',credit-(gross+travel-remaining),'caixa_diarias',cash,'caixa_passagens',pcash);
end;$$;
revoke all on function direct_private.supervisor_plan(bigint,bigint) from public,anon,authenticated;

create function public.direct_supervisor_acerto(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$begin return direct_private.supervisor_plan((p->>'diarista_id')::bigint,(p->>'pedido_id')::bigint);end;$$;
revoke all on function public.direct_supervisor_acerto(jsonb) from public,anon;grant execute on function public.direct_supervisor_acerto(jsonb) to authenticated;

create function direct_private.supervisor_closing(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a date:=(p->>'inicio')::date;b date:=(p->>'fim')::date;net text:=coalesce(p->>'rede','');today date:=(now() at time zone 'America/Fortaleza')::date;rows jsonb;mov jsonb;missing jsonb;metrics jsonb;result jsonb;
begin
 if auth.uid() is null or coalesce(direct_private.member_role(),'') not in ('admin','financeiro') then raise exception 'Somente administrador ou Financeiro.' using errcode='42501';end if;
 if a is null or b is null or a>b or b-a>366 then raise exception 'Escolha um período em ordem crescente de até 366 dias.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'pedido_id',s.pedido_id,'diarista_id',d.diarista_id,'nome',w.nome,'cpf',w.cpf,'rede',coalesce(o.supermercado,d.local),'loja',coalesce(o.unidade,d.local),'setor',d.setor,'data',d.data,'valor_centavos',d.valor_centavos,'receita_centavos',d.valor_recebido_centavos,'data_pagamento',d.data_pagamento) order by d.id),'[]') into rows from public.diarias d join public.diaristas w on w.id=d.diarista_id left join public.pedido_escalas s on s.id=d.pedido_escala_id left join public.pedidos o on o.id=s.pedido_id where d.data between a and b and (net='' or coalesce(o.supermercado,d.local)=net);
 select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]') into mov from public.supervisor_registros r join public.pedidos o on o.id=r.pedido_id where r.tipo in ('adiantamento','passagem') and (r.dados->>'data')::date between a and b and (net='' or o.supermercado=net) and not exists(select 1 from public.supervisor_registros v where v.tipo='estorno' and (v.dados->>'registro_id')::bigint=r.id);
 with slots as(select o.id,o.situacao,o.quantidade_diaristas,t.value->>'data' as shift_day from public.pedidos o cross join lateral jsonb_array_elements(o.turnos)t where (t.value->>'data')::date between a and least(b,today) and (net='' or o.supermercado=net)),data as(select t.*, (select count(*) from public.pedido_escalas s where s.pedido_id=t.id and s.data=t.shift_day::date and s.status='presente') presence,(select count(*) from public.pedido_escalas s where s.pedido_id=t.id and s.data=t.shift_day::date and s.status='falta') absent,(select count(*) from public.pedido_escalas s where s.pedido_id=t.id and s.data=t.shift_day::date and s.status='desistiu') withdrawn,(select count(*) from public.pedido_escalas s where s.pedido_id=t.id and s.data=t.shift_day::date and s.status='escalada' and t.situacao<>'cancelado') pending from slots t)
 select jsonb_build_object('solicitadas',coalesce(sum(case when situacao='cancelado' then presence else quantidade_diaristas end),0),'atendidas',coalesce(sum(presence),0),'faltas',coalesce(sum(absent),0),'desistencias',coalesce(sum(withdrawn),0),'presencas_pendentes',coalesce(sum(pending),0),'demanda_finalizada',coalesce(sum(case when shift_day::date<today then case when situacao='cancelado' then presence else quantidade_diaristas end else 0 end),0),'atendidas_finalizadas',coalesce(sum(case when shift_day::date<today then presence else 0 end),0)) into metrics from data;
 metrics:=metrics||jsonb_build_object('nao_atendidas',greatest(0,(metrics->>'solicitadas')::bigint-(metrics->>'atendidas')::bigint));
 select coalesce(jsonb_agg('Diária #'||(r->>'id')||' com valor incompleto.'),'[]') into missing from jsonb_array_elements(rows) r where r->'valor_centavos'='null'::jsonb or r->'receita_centavos'='null'::jsonb;
 if (metrics->>'presencas_pendentes')::bigint>0 then missing:=missing||jsonb_build_array((metrics->>'presencas_pendentes')||' presença(s) ainda a conferir no período.');end if;
 if b>today then missing:=missing||jsonb_build_array('O período inclui dias futuros; aguarde para concluir o fechamento.');end if;
 result:=jsonb_build_object('inicio',a,'fim',b,'rede',case when net='' then 'Todas as redes' else net end,'diarias',rows,'movimentos',mov,'pendencias',missing,'metricas',metrics,'totais',jsonb_build_object('despesas_centavos',(select coalesce(sum(l.valor_centavos),0) from public.financeiro_lancamentos l left join public.empresa_registros er on er.id=l.empresa_registro_id left join public.pedidos o on o.id=er.pedido_id where l.tipo='despesa' and coalesce((er.dados->>'data')::date,l.vencimento) between a and b and (net='' or o.supermercado=net)),'receita_centavos',(select coalesce(sum((r->>'receita_centavos')::bigint),0) from jsonb_array_elements(rows)r),'diarias_centavos',(select coalesce(sum((r->>'valor_centavos')::bigint),0) from jsonb_array_elements(rows)r),'passagens_centavos',(select coalesce(sum((r->'dados'->>'valor_centavos')::bigint),0) from jsonb_array_elements(mov)r where r->>'tipo'='passagem'),'adiantamentos_centavos',(select coalesce(sum((r->'dados'->>'valor_centavos')::bigint),0) from jsonb_array_elements(mov)r where r->>'tipo'='adiantamento')));
 return result||jsonb_build_object('assinatura',md5(result::text));
end;$$;
revoke all on function direct_private.supervisor_closing(jsonb) from public,anon,authenticated;
create function public.direct_supervisor_fechamento(p jsonb) returns jsonb language sql stable security definer set search_path='' as $$select direct_private.supervisor_closing(p)$$;
revoke all on function public.direct_supervisor_fechamento(jsonb) from public,anon;grant execute on function public.direct_supervisor_fechamento(jsonb) to authenticated;

create function public.direct_supervisor_registro(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare kind text:=p->>'tipo';key text:=p->>'chave';old public.supervisor_registros;r public.supervisor_registros;target public.supervisor_registros;wid bigint;oid bigint;day date;method text;d jsonb;amount bigint;bid bigint;ids bigint[];
begin
 if auth.uid() is null or coalesce(direct_private.member_role(),'') not in ('admin','financeiro') then raise exception 'Somente administrador ou Financeiro.' using errcode='42501';end if;
 if key is null or key !~ '^[A-Za-z0-9:_-]{8,120}$' then raise exception 'Chave inválida.';end if;
 perform pg_advisory_xact_lock(hashtextextended('supervisor-key:'||key,0));select * into old from public.supervisor_registros where chave=key;
 if old.id is not null then if old.dados->'solicitacao'<>p-'chave' then raise exception 'Essa chave já foi usada para outra operação.';end if;return to_jsonb(old)||jsonb_build_object('repetido',true);end if;
 if kind in ('adiantamento','passagem','acerto') then
  if jsonb_typeof(p->'diarista_id') is distinct from 'number' or jsonb_typeof(p->'pedido_id') is distinct from 'number' then raise exception 'Escolha o diarista e o pedido.';end if;wid:=(p->>'diarista_id')::bigint;oid:=(p->>'pedido_id')::bigint;
  -- Shared worker lock prevents overlapping settlements or a movement racing the settlement.
  perform id from public.diaristas where id=wid for update;
  if not exists(select 1 from public.pedido_escalas where pedido_id=oid and diarista_id=wid) then raise exception 'O diarista deve ter uma escala neste pedido.';end if;
  day:=(p->>'data')::date;method:=trim(coalesce(p->>'forma',''));if day is null or day>(now() at time zone 'America/Fortaleza')::date then raise exception 'Registro realizado não pode ter data futura.';end if;
  if length(method)>80 or (kind in ('adiantamento','acerto') and method='') then raise exception 'Informe a forma de pagamento.';end if;
  if kind='acerto' then
   perform d0.id from public.diarias d0 join public.pedido_escalas s on s.id=d0.pedido_escala_id where s.pedido_id=oid and d0.diarista_id=wid order by d0.id for update of d0;
   d:=direct_private.supervisor_plan(wid,oid);if jsonb_array_length(d->'diaria_ids')+jsonb_array_length(d->'passagem_ids')=0 then raise exception 'Não há valores pendentes para acertar.';end if;
   if p->'conferencia' is distinct from d then raise exception 'O saldo mudou. Atualize e confira novamente.';end if;
  else
   if jsonb_typeof(p->'valor_centavos') is distinct from 'number' or p->>'valor_centavos' !~ '^[0-9]+$' then raise exception 'Valor inválido.';end if;amount:=(p->>'valor_centavos')::bigint;
   if amount not between 1 and 1000000000 or length(trim(coalesce(p->>'motivo',''))) not between 1 and 500 then raise exception 'Informe um valor positivo e o motivo.';end if;
   d:=jsonb_build_object('valor_centavos',amount,'motivo',trim(p->>'motivo'));
  end if;
  d:=d||jsonb_build_object('data',day,'forma',method,'nome',(select nome from public.diaristas where id=wid));
 elsif kind='fechamento' then
  -- Stable snapshot under source locks: later edits are detected by the next comparison.
  lock table public.diarias,public.pedido_escalas,public.pedidos,public.supervisor_registros in share row exclusive mode;
  d:=direct_private.supervisor_closing(p);if jsonb_array_length(d->'pendencias')>0 then raise exception 'Resolva as pendências antes de fechar.';end if;
  if p->>'assinatura' is distinct from d->>'assinatura' then raise exception 'O levantamento mudou. Atualize e confira novamente.';end if;
  if length(coalesce(p->>'observacoes',''))>1000 then raise exception 'Observações muito longas.';end if;d:=d||jsonb_build_object('observacoes',coalesce(p->>'observacoes',''));
 elsif kind='estorno' then
  select * into target from public.supervisor_registros where id=(p->>'registro_id')::bigint for update;
  if target.id is null or target.tipo not in ('adiantamento','passagem') then raise exception 'Escolha um movimento que possa ser anulado.';end if;
  perform id from public.diaristas where id=target.diarista_id for update;
  if exists(select 1 from public.supervisor_registros v where v.tipo='estorno' and (v.dados->>'registro_id')::bigint=target.id or v.tipo='acerto' and (v.dados->'passagem_ids' @> jsonb_build_array(target.id) or exists(select 1 from jsonb_array_elements(v.dados->'abatimentos') x where (x->>'id')::bigint=target.id))) then raise exception 'O movimento já foi anulado ou utilizado em acerto. Preserve seu histórico.';end if;
  if length(trim(coalesce(p->>'motivo',''))) not between 1 and 500 then raise exception 'Informe o motivo da anulação.';end if;wid:=target.diarista_id;oid:=target.pedido_id;d:=jsonb_build_object('registro_id',target.id,'motivo',trim(p->>'motivo'));
 else raise exception 'Operação não reconhecida.';end if;
 insert into public.supervisor_registros(tipo,pedido_id,diarista_id,dados,chave,autor) values(kind,oid,wid,d||jsonb_build_object('solicitacao',p-'chave'),key,auth.jwt()->>'email') returning * into r;
 if kind='acerto' then
  select array_agg(value::bigint) into ids from jsonb_array_elements_text(d->'diaria_ids');
  if cardinality(ids)>0 and (d->>'saldo_centavos')::bigint>0 then insert into public.pagamento_lotes(diarista_id,valor_centavos,data_pagamento,forma,quantidade) values(wid,(d->>'saldo_centavos')::bigint,day,method,cardinality(ids)) returning id into bid;end if;
  update public.diarias set data_pagamento=day,forma_pagamento=method,pagamento_lote_id=bid where id=any(ids);
 end if;
 return to_jsonb(r);
end;$$;
revoke all on function public.direct_supervisor_registro(jsonb) from public,anon;grant execute on function public.direct_supervisor_registro(jsonb) to authenticated;

create function direct_private.supervisor_daily_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if old.data_pagamento is not null and exists(select 1 from public.supervisor_registros r where r.tipo='acerto' and r.dados->'diaria_ids' @> jsonb_build_array(old.id)) and (new.data_pagamento is distinct from old.data_pagamento or new.valor_centavos is distinct from old.valor_centavos or new.pagamento_lote_id is distinct from old.pagamento_lote_id) then raise exception 'Acerto preservado no extrato. Não altere os valores ou a quitação por outra tela.';end if;
 if old.data_pagamento is null and new.data_pagamento is not null and exists(select 1 from public.pedido_escalas s join public.supervisor_registros r on r.pedido_id=s.pedido_id and r.diarista_id=old.diarista_id where s.id=old.pedido_escala_id and r.tipo in ('adiantamento','passagem') and not exists(select 1 from public.supervisor_registros v where v.tipo='estorno' and (v.dados->>'registro_id')::bigint=r.id)) and not exists(select 1 from public.supervisor_registros r where r.tipo='acerto' and r.dados->'diaria_ids' @> jsonb_build_array(old.id)) then raise exception 'Confira adiantamentos e passagens no Extrato do diarista antes de pagar.';end if;return new;
end;$$;
revoke all on function direct_private.supervisor_daily_guard() from public,anon,authenticated;
create trigger supervisor_daily_guard before update on public.diarias for each row execute function direct_private.supervisor_daily_guard();

create function direct_private.backup_snapshot_v11() returns jsonb language sql stable security invoker set search_path='' as $$
 with data as(select direct_private.backup_snapshot_v10()->'tables'||jsonb_build_object('supervisor_registros',(select coalesce(jsonb_agg(to_jsonb(r) order by id),'[]') from public.supervisor_registros r)) tables)
 select jsonb_build_object('format','direct-data-v11','exportedAt',now(),'tables',tables,'snapshot',jsonb_build_object('consistent',true,'counts',(select jsonb_object_agg(key,jsonb_array_length(value)) from jsonb_each(data.tables)))) from data;$$;
revoke all on function direct_private.backup_snapshot_v11() from public,anon,authenticated;
create function public.direct_backup_snapshot_v11() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null or coalesce(direct_private.member_role(),'')<>'admin' then raise exception 'Somente administrador.' using errcode='42501';end if;return direct_private.backup_snapshot_v11();end;$$;
revoke all on function public.direct_backup_snapshot_v11() from public,anon;grant execute on function public.direct_backup_snapshot_v11() to authenticated;
do $$declare ddl text;begin select pg_get_functiondef('public.direct_backup_bundle(text,uuid)'::regprocedure) into ddl;execute replace(ddl,'direct_private.backup_snapshot_v10()','direct_private.backup_snapshot_v11()');end;$$;

DO $$DECLARE r record;current_digest text;BEGIN FOR r IN SELECT * FROM pg_temp.supervisor_preservation_check LOOP EXECUTE format('SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),''[]'')::text) FROM public.%I t',r.tabela) INTO current_digest;IF current_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'Preservation check failed: %',r.tabela;END IF;END LOOP;END;$$;
